#include <iostream>
#include <vector>
int main() {
    std::vector<int> v{5, 6, 7};
    std::cout << v.at(5) << "\n";
    return 0;
}

#include <iostream>
#include <vector>
int main() {
    std::vector<int> v{1, 2, 3, 4};
    for (int i = 0; i < 2; i++) {
        int t = v[i]; v[i] = v[3 - i]; v[3 - i] = t;
    }
    for (int x : v) std::cout << x;
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>
int main() {
    std::vector<int> v;
    for (int i = 0; i < 5; i++) v.push_back(i);
    std::cout << v.size() << " " << v.capacity() << "\n";
    return 0;
}

#include <iostream>
#include <vector>
int main() {
    std::vector<int> v{2, 2, 2};
    for (int i = 0; i < v.size(); i++) {
        if (v[i] == 2) v.erase(v.begin() + i);
    }
    std::cout << v.size() << "\n";
    return 0;
}

#include <iostream>
#include <vector>
int main() {
    std::vector<int> v{3, 1, 4, 1, 5};
    int best = v[0], count = 0;
    for (int x : v) {
        if (x > best) { best = x; count++; }
    }
    std::cout << count << "\n";
    return 0;
}
